use std::rc::Rc;
use std::cell::RefCell;
use xamlx::testing::FakeTypeSystem;
use xamlx::type_system::{get_type, get_types};
fn main() {
    let ts=FakeTypeSystem::new();
    let object=get_type(&*ts,"System.Object").unwrap();
    let before=Rc::strong_count(&object);
    let trace=RefCell::new(Vec::new());
    let err=get_types(["System.Object", "Absent.First","Absent.Second"], |name| {
        trace.borrow_mut().push(name.to_owned());
        get_type(&*ts,name)
    });
    assert!(err.is_err());
    assert_eq!(trace.borrow().as_slice(), ["System.Object","Absent.First"]);
    assert_eq!(before,Rc::strong_count(&object));
    std::panic::set_hook(Box::new(|_|{}));
    let outcome=std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        get_types(["System.Object","Panic","Absent.Second"], |name| {
            if name=="Panic"{panic!("inside host lookup")}
            get_type(&*ts,name)
        })
    }));
    assert!(outcome.is_err());assert_eq!(before,Rc::strong_count(&object));
    assert!(get_types::<0>([],|_|panic!("empty group")).unwrap().is_empty());
    let [a,b,c]=get_types(["System.String","System.Object","System.Object"],|name|get_type(&*ts,name)).unwrap();
    assert!(a.equals(&*get_type(&*ts,"System.String").unwrap()));
    assert!(Rc::ptr_eq(&b,&object)&&Rc::ptr_eq(&c,&object));
    println!("Error short-circuit, refcount on error and panic, zero length, input order and repeated handles verified.");
}

